INSERT INTO `pertanyaan` (`id_pertanyaan`, `id_evidence`, `kode_pertanyaan`, `kategori`, `pertanyaan`, `urutan`) VALUES
(1, 1, 'P0001', 'tujuan_karier', 'Saya ingin membantu menyembuhkan orang yang sakit', 0),
(2, 2, 'P0002', 'minat', 'Saya menyukai pelajaran Biologi dan tertarik pada tubuh manusia', 1),
(3, 3, 'P0003', 'kepribadian', 'Saya tidak takut melihat darah atau luka', 2),
(4, 4, 'P0004', 'minat', 'Saya tertarik pada kesehatan gigi dan mulut', 3),
(5, 5, 'P0005', 'bakat', 'Saya cekatan dan teliti menggunakan tangan untuk pekerjaan presisi', 4),
(6, 6, 'P0006', 'minat', 'Saya tertarik pada obat-obatan dan cara kerja senyawa kimia dalam tubuh', 5),
(7, 7, 'P0007', 'tujuan_karier', 'Saya ingin bekerja sebagai apoteker atau di industri farmasi', 6),
